14	// What a step may say (docs/architecture/scanning.md, "Writing a Resolution,
15	// Steps and Repro for a new finding"). A step is an English US sentence with one
16	// action and no key name: the same fix is read in the finding detail, in `scan_result`
17	// and in the README, and a key name is true in only one of them.
18	//
19	// stepProblems checks what can be checked without judging prose:
20	//
21	//	S1  no key name: a modifier chord (ctrl+, alt+, shift+, cmd+), `esc` or `ctrl`
22	//	    on their own, a letter between angle brackets (<Y>, <Enter>), a function key
23	//	    (F1 to F12), "<name> key" for a usual key name, and the words press, hit,
24	//	    keystroke, keybinding and shortcut;
25	//	S2  no step is empty, padded with blanks, or spread over several lines;
26	//	S3  a step starts with a capital letter, except right after a step that ends in
27	//	    ", or" (the two-step alternative of a load restrictor failure, written that
28	//	    way before the convention; its test pins the exact text);
29	//	S4  a step ends with a period, except one that ends in ", or" and is followed by
30	//	    its alternative;
31	//	S5  no step appears twice in the list.
32	//
33	// What it does not check, because no reliable check exists: that the first word is an
34	// imperative verb (a step may open with "If this reference points outside…"), that
35	// there is one action per step, and that the English is US. A bare "enter", "tab" or
36	// "return" is not flagged either: each is also an ordinary verb or noun.
37	var keyNamePatterns = []*regexp.Regexp{
38		regexp.MustCompile(`(?i)\b(?:ctrl|alt|shift|cmd|super)\+`),
39		regexp.MustCompile(`(?i)\b(?:ctrl|esc)\b`),
40		regexp.MustCompile(`<[A-Za-z][A-Za-z0-9]*>`),
41		regexp.MustCompile(`\bF(?:[1-9]|1[0-2])\b`),
42		regexp.MustCompile(`(?i)\b(?:enter|return|esc|escape|tab|space|backspace|delete|arrow|up|down|left|right)\s+key\b`),
43		regexp.MustCompile(`(?i)\b(?:press|presses|pressed|pressing|hit|keystrokes?|keybindings?|shortcuts?)\b`),
44	}
45	
46	const alternativeEnd = ", or"
47	
48	func stepProblems(steps []string) []string {
49		var problems []string
50		seen := map[string]bool{}
51		for i, s := range steps {
52			label := fmt.Sprintf("step %d %q", i+1, s)
53			switch {
54			case s == "":
55				problems = append(problems, label+": empty")
56				continue
57			case s != strings.TrimSpace(s) || strings.ContainsAny(s, "\n\r\t"):
58				problems = append(problems, label+": blanks around it or a line break inside")
59			}
60			for _, re := range keyNamePatterns {
61				if m := re.FindString(s); m != "" {
62					problems = append(problems, fmt.Sprintf("%s: names a key (%q)", label, m))
63				}
64			}
65			afterAlternative := i > 0 && strings.HasSuffix(steps[i-1], alternativeEnd)
66			first, _ := utf8.DecodeRuneInString(s)
67			if !unicode.IsUpper(first) && !afterAlternative {
68				problems = append(problems, label+": does not start with a capital letter")
69			}
70			last := i == len(steps)-1
71			switch {
72			case strings.HasSuffix(s, "."):
73			case strings.HasSuffix(s, alternativeEnd) && !last:
74			default:
75				problems = append(problems, label+": does not end with a period")
76			}
77			if seen[s] {
78				problems = append(problems, label+": appears twice")
79			}
80			seen[s] = true
81		}
82		return problems
83	}
84	
85	func TestTheStepGuardCatchesWhatTheConventionForbids(t *testing.T) {
86		cases := []struct {
87			name  string
88			steps []string
89			want  string
90		}{
91			{"a chord", []string{"Press ctrl+r to scan again."}, "names a key"},
92			{"press alone", []string{"Press the key shown in the footer."}, "names a key"},
93			{"an angle key", []string{"Open the detail with <Y> and read it."}, "names a key"},
94			{"a key word", []string{"Use the esc key to go back."}, "names a key"},
95			{"a function key", []string{"Open the help with F1."}, "names a key"},
96			{"a shortcut", []string{"Use the shortcut in the header."}, "names a key"},
97			{"no capital", []string{"run helm template charts/api."}, "capital letter"},
98			{"no period", []string{"Run helm template charts/api"}, "period"},
99			{"empty", []string{""}, "empty"},
100			{"a line break", []string{"Run it.\nThen run it again."}, "line break"},
101			{"a duplicate", []string{"Run it.", "Run it."}, "twice"},
102			{"a dangling alternative", []string{"Do this, or"}, "period"},
103			{"a lowercase step after a plain one", []string{"Do this.", "do that."}, "capital letter"},
104		}
105		for _, c := range cases {
106			got := strings.Join(stepProblems(c.steps), "\n")
107			if !strings.Contains(got, c.want) {
108				t.Errorf("%s: problems = %q, want one mentioning %q", c.name, got, c.want)
109			}
110		}
111	}
