128	// escape the guard by being forgotten.
129	func stepSamples() map[string][][]string {
130		restrictor := loadRestrictorStderr
131		problem := kubeconformFieldProblem{Path: "/spec/replicas", Msg: "got string, want integer"}
132		unknownField := kubeconformFieldProblem{Path: "/spec/", Msg: "additional properties 'foo' not allowed"}
133		resource := kubeconformResource{Kind: "Deployment", Version: "apps/v1"}
134		return map[string][][]string{
135			"renderSteps": {
136				renderSteps(SourceHelm, "charts/api", ToolSourceBinary, "boom"),
137				renderSteps(SourceKustomize, "overlays/dev", ToolSourceBinary, "boom"),
138				renderSteps(SourceKustomize, "overlays/dev", ToolSourceBinary, restrictor),
139				renderSteps(SourceKustomize, "overlays/dev", ToolSourceContainer, restrictor),
140				renderSteps(SourceKustomize, "overlays/dev", ToolSourceContainer, "no such file or directory"),
141				renderSteps(SourceKustomize, "overlays/dev", ToolSourceContainer, "evalsymlink failure"),
142			},
143			"helmLintSteps": {helmLintSteps("templates/deployment.yaml", "charts/api")},
144			"schemaSteps": {
145				schemaSteps(resource, problem, "1.36.0", ""),
146				schemaSteps(resource, problem, "", ""),
147				schemaSteps(resource, problem, "1.36.0", "helm"),
148				schemaSteps(resource, problem, "", "kustomize"),
149				schemaSteps(resource, unknownField, "1.36.0", ""),
150				schemaSteps(resource, kubeconformFieldProblem{Msg: "invalid"}, "1.36.0", ""),
151			},
152			"secretSteps": {secretSteps()},
153		}
154	}
