156	func TestEveryStepsFunctionHasASample(t *testing.T) {
157		samples := stepSamples()
158		src := parseGuardSources(t, map[string]string{"steps.go": packageGuardSources(t)["steps.go"]})[0]
159		var discovered []string
160		for _, d := range src.file.Decls {
161			fd, ok := d.(*ast.FuncDecl)
162			if !ok || !strings.HasSuffix(fd.Name.Name, "Steps") {
163				continue
164			}
165			discovered = append(discovered, fd.Name.Name)
166			if _, ok := samples[fd.Name.Name]; !ok {
167				t.Errorf("%s writes steps and has no entry in stepSamples: add inputs that reach each of its branches", fd.Name.Name)
168			}
169		}
170		if len(discovered) < 4 {
171			t.Errorf("found %d *Steps functions in steps.go, expected at least 4: did the file move?", len(discovered))
172		}
173		for name := range samples {
174			if !slices.Contains(discovered, name) {
175				t.Errorf("stepSamples has %s, which steps.go no longer defines", name)
176			}
177		}
178	}
