140	// calleeName is the name of the function a call names directly, or "".
141	func calleeName(call *ast.CallExpr) string {
142		switch f := call.Fun.(type) {
143		case *ast.Ident:
144			return f.Name
145		case *ast.SelectorExpr:
146			return f.Sel.Name
147		}
148		return ""
149	}
150	
151	func flattenParams(decl *ast.FuncDecl) map[string]int {
152		params := map[string]int{}
153		i := 0
154		for _, field := range decl.Type.Params.List {
155			if len(field.Names) == 0 {
156				i++
157				continue
158			}
159			for _, n := range field.Names {
160				params[n.Name] = i
161				i++
162			}
163		}
164		return params
165	}
