167	// findWrappers returns the functions whose every return is a single call to a
168	// producer (or to a wrapper already found): renderRepro around localRepro.
169	func findWrappers(funcs map[string]guardFunc, rule fieldRule) map[string]bool {
170		wrappers := map[string]bool{}
171		for changed := true; changed; {
172			changed = false
173			for name, fn := range funcs {
174				if wrappers[name] || fn.decl.Body == nil || rule.producer(name, nil) {
175					continue
176				}
177				returns, all := 0, true
178				ast.Inspect(fn.decl.Body, func(n ast.Node) bool {
179					if _, lit := n.(*ast.FuncLit); lit {
180						return false
181					}
182					ret, ok := n.(*ast.ReturnStmt)
183					if !ok {
184						return true
185					}
186					returns++
187					call, isCall := (*ast.CallExpr)(nil), false
188					if len(ret.Results) == 1 {
189						call, isCall = ret.Results[0].(*ast.CallExpr)
190					}
191					if !isCall || !rule.producer(calleeName(call), wrappers) {
192						all = false
193					}
194					return true
195				})
196				if returns > 0 && all {
197					wrappers[name] = true
198					changed = true
199				}
200			}
201		}
202		return wrappers
203	}
