205	type scopeFacts struct {
206		produced map[string]bool // names a producer call defined
207		dirty    map[string]bool // names something else assigned
208	}
209	
210	// factsOf reads what a function assigns to which name.
211	func factsOf(body ast.Node, rule fieldRule, wrappers map[string]bool) scopeFacts {
212		facts := scopeFacts{map[string]bool{}, map[string]bool{}}
213		note := func(lhs []ast.Expr, rhs []ast.Expr) {
214			if len(rhs) == 1 {
215				if call, ok := rhs[0].(*ast.CallExpr); ok {
216					for i, l := range lhs {
217						name := exprString(l)
218						if i == 0 && rule.producer(calleeName(call), wrappers) {
219							facts.produced[name] = true
220						} else {
221							facts.dirty[name] = true
222						}
223					}
224					return
225				}
226			}
227			for i, l := range lhs {
228				name := exprString(l)
229				if name == "_" || name == "" {
230					continue
231				}
232				if len(lhs) == len(rhs) {
233					if call, ok := rhs[i].(*ast.CallExpr); ok && rule.producer(calleeName(call), wrappers) {
234						facts.produced[name] = true
235						continue
236					}
237				}
238				facts.dirty[name] = true
239			}
240		}
241		ast.Inspect(body, func(n ast.Node) bool {
242			switch s := n.(type) {
243			case *ast.AssignStmt:
244				note(s.Lhs, s.Rhs)
245			case *ast.ValueSpec:
246				names := make([]ast.Expr, len(s.Names))
247				for i, id := range s.Names {
248					names[i] = id
249				}
250				note(names, s.Values)
251			case *ast.RangeStmt:
252				for _, e := range []ast.Expr{s.Key, s.Value} {
253					if e != nil {
254						facts.dirty[exprString(e)] = true
255					}
256				}
257			}
258			return true
259		})
260		return facts
261	}
