263	// fieldViolations reports every site that sets rule.field from something the rule
264	// does not accept, as "file:line: function: reason", sorted. found is how many
265	// sites it examined, so a caller can tell a pass from a blind pass.
266	func fieldViolations(sources []guardSource, rule fieldRule) (violations []string, found int) {
267		funcs := map[string]guardFunc{}
268		for _, src := range sources {
269			for _, d := range src.file.Decls {
270				if fd, ok := d.(*ast.FuncDecl); ok {
271					funcs[fd.Name.Name] = guardFunc{fd, src, flattenParams(fd)}
272				}
273			}
274		}
275		wrappers := findWrappers(funcs, rule)
276		factsCache := map[string]scopeFacts{}
277		facts := func(fn guardFunc) scopeFacts {
278			key := fn.decl.Name.Name
279			if f, ok := factsCache[key]; ok {
280				return f
281			}
282			f := factsOf(fn.decl.Body, rule, wrappers)
283			factsCache[key] = f
284			return f
285		}
286	
287		var check func(fn guardFunc, e ast.Expr, seen map[string]bool) string
288		check = func(fn guardFunc, e ast.Expr, seen map[string]bool) string {
289			if rule.zero(e) {
290				return ""
291			}
292			if call, ok := e.(*ast.CallExpr); ok {
293				if rule.producer(calleeName(call), wrappers) {
294					return ""
295				}
296				return "value comes from a call to " + calleeName(call) + ", not from a producer"
297			}
298			name := exprString(e)
299			if name == "" {
300				return "value is an expression the guard does not follow; use a variable a producer returned"
301			}
302			f := facts(fn)
303			if f.dirty[name] {
304				return name + " is assigned from something other than a producer"
305			}
306			if f.produced[name] {
307				return ""
308			}
309			idx, isParam := fn.params[name]
310			if !isParam {
311				return name + " is not defined by a producer call in the function"
312			}
313			key := fn.decl.Name.Name + "#" + name
314			if seen[key] {
315				return ""
316			}
317			seen[key] = true
318			callers := 0
319			for _, caller := range funcs {
320				if caller.decl.Body == nil {
321					continue
322				}
323				var bad string
324				ast.Inspect(caller.decl.Body, func(n ast.Node) bool {
325					call, ok := n.(*ast.CallExpr)
326					if !ok || calleeName(call) != fn.decl.Name.Name {
327						return true
328					}
329					callers++
330					if idx >= len(call.Args) {
331						bad = "a call to " + fn.decl.Name.Name + " does not pass " + name
332					} else if why := check(caller, call.Args[idx], seen); why != "" && bad == "" {
333						bad = "via " + caller.decl.Name.Name + " at " + pos(caller.source, call) + ": " + why
334					}
335					return true
336				})
337				if bad != "" {
338					return name + " is a parameter and " + bad
339				}
340			}
341			if callers == 0 {
342				return name + " is a parameter nobody in the package passes a value to"
343			}
344			return ""
345		}
346	
347		report := func(fn *guardFunc, src guardSource, at ast.Node, why string) {
348			fname := "(package level)"
349			if fn != nil {
350				fname = fn.decl.Name.Name
351			}
352			violations = append(violations, pos(src, at)+": "+fname+": "+rule.field+": "+why)
353		}
354		visit := func(fn *guardFunc, src guardSource, root ast.Node) {
355			ast.Inspect(root, func(n ast.Node) bool {
356				var why string
357				switch s := n.(type) {
358				case *ast.CompositeLit:
359					if id, ok := s.Type.(*ast.Ident); ok && id.Name == "Finding" && len(s.Elts) > 0 {
360						if _, keyed := s.Elts[0].(*ast.KeyValueExpr); !keyed {
361							report(fn, src, s, "positional Finding literal: use keyed fields so the guard can read them")
362						}
363					}
364				case *ast.KeyValueExpr:
365					if id, ok := s.Key.(*ast.Ident); ok && id.Name == rule.field {
366						found++
367						if fn == nil {
368							if !rule.zero(s.Value) {
369								why = "set at package level"
370							}
371						} else {
372							why = check(*fn, s.Value, map[string]bool{})
373						}
374						if why != "" {
375							report(fn, src, s, why)
376						}
377					}
378				case *ast.AssignStmt:
379					for i, l := range s.Lhs {
380						sel, ok := l.(*ast.SelectorExpr)
381						if !ok || sel.Sel.Name != rule.field {
382							continue
383						}
384						found++
385						switch {
386						case fn == nil:
387							why = "set at package level"
388						case s.Tok != token.ASSIGN && s.Tok != token.DEFINE:
389							why = "modified in place with " + s.Tok.String()
390						case len(s.Rhs) == len(s.Lhs):
391							why = check(*fn, s.Rhs[i], map[string]bool{})
392						case len(s.Rhs) == 1:
393							call, isCall := s.Rhs[0].(*ast.CallExpr)
394							if !isCall || i != 0 || !rule.producer(calleeName(call), wrappers) {
395								why = "tuple assignment that is not a producer's first result"
396							}
397						}
398						if why != "" {
399							report(fn, src, s, why)
400						}
401					}
402				}
403				return true
404			})
405		}
406		for _, src := range sources {
407			for _, d := range src.file.Decls {
408				if fd, ok := d.(*ast.FuncDecl); ok {
409					if fd.Body != nil {
410						fn := funcs[fd.Name.Name]
411						visit(&fn, src, fd.Body)
412					}
413					continue
414				}
415				visit(nil, src, d)
416			}
417		}
418		sort.Strings(violations)
419		return violations, found
420	}
