151	func flattenParams(decl *ast.FuncDecl) map[string]int {
152		params := map[string]int{}
153		i := 0
154		for _, field := range decl.Type.Params.List {
155			if len(field.Names) == 0 {
156				i++
157				continue
158			}
159			for _, n := range field.Names {
160				params[n.Name] = i
161				i++
162			}
163		}
164		return params
165	}
