263	// fieldViolations reports every site that sets rule.field from something the rule
264	// does not accept, as "file:line: function: reason", sorted. found is how many
265	// sites it examined, so a caller can tell a pass from a blind pass.
266	func fieldViolations(sources []guardSource, rule fieldRule) (violations []string, found int) {
267		funcs := map[string]guardFunc{}
268		for _, src := range sources {
