275		wrappers := findWrappers(funcs, rule)
276		factsCache := map[string]scopeFacts{}
277		facts := func(fn guardFunc) scopeFacts {
278			key := fn.decl.Name.Name
279			if f, ok := factsCache[key]; ok {
280				return f
281			}
282			f := factsOf(fn.decl.Body, rule, wrappers)
283			factsCache[key] = f
284			return f
285		}
