287		var check func(fn guardFunc, e ast.Expr, seen map[string]bool) string
288		check = func(fn guardFunc, e ast.Expr, seen map[string]bool) string {
289			if rule.zero(e) {
290				return ""
291			}
292			if call, ok := e.(*ast.CallExpr); ok {
293				if rule.producer(calleeName(call), wrappers) {
294					return ""
295				}
296				return "value comes from a call to " + calleeName(call) + ", not from a producer"
297			}
298			name := exprString(e)
299			if name == "" {
300				return "value is an expression the guard does not follow; use a variable a producer returned"
301			}
302			f := facts(fn)
303			if f.dirty[name] {
304				return name + " is assigned from something other than a producer"
305			}
306			if f.produced[name] {
307				return ""
308			}
309			idx, isParam := fn.params[name]
310			if !isParam {
311				return name + " is not defined by a producer call in the function"
312			}
313			key := fn.decl.Name.Name + "#" + name
314			if seen[key] {
315				return ""
316			}
317			seen[key] = true
318			callers := 0
319			for _, caller := range funcs {
320				if caller.decl.Body == nil {
321					continue
322				}
323				var bad string
324				ast.Inspect(caller.decl.Body, func(n ast.Node) bool {
325					call, ok := n.(*ast.CallExpr)
326					if !ok || calleeName(call) != fn.decl.Name.Name {
327						return true
328					}
329					callers++
330					if idx >= len(call.Args) {
331						bad = "a call to " + fn.decl.Name.Name + " does not pass " + name
332					} else if why := check(caller, call.Args[idx], seen); why != "" && bad == "" {
333						bad = "via " + caller.decl.Name.Name + " at " + pos(caller.source, call) + ": " + why
334					}
335					return true
336				})
337				if bad != "" {
338					return name + " is a parameter and " + bad
339				}
340			}
341			if callers == 0 {
342				return name + " is a parameter nobody in the package passes a value to"
343			}
344			return ""
345		}
346	
347		report := func(fn *guardFunc, src guardSource, at ast.Node, why string) {
348			fname := "(package level)"
349			if fn != nil {
